;; curriculum: Multivariable (undergrad) — gradient; prerequisites: partial, vector
;; math target: the gradient ∇f points in the direction of steepest ascent; its length is the slope there.

app riya-level-gradient "1.1.0"
"riya level 25 · Steepest Way Up — a gaussian hill z = 1 + 5·e^(−x²/18). The purple arrows are ∇f, always aiming at the summit. A downhill drift (−∇f) tugs you away; follow the arrows uphill to the summit star. Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup, rendered through math-canvas."

;; @exposure internal

orbital RiyaGradientOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaGradientBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaGradientPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaGradientFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  type RiyaGradientFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaGradientPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaGradientCurveSample = {
    x : number!
    y : number!
  }
  type RiyaGradientCurve = {
    label : string
    color : string
    samples : [RiyaGradientCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaGradientGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaGradientFieldVector = {
    x : number!
    y : number!
    vx : number!
    vy : number!
    color : string
    label : string
  }
  type RiyaGradientDriftRegion = {
    id : string!
    x0 : number!
    x1 : number!
    y0 : number!
    y1 : number!
    ax : number!
    ay : number!
  }

  entity RiyaGradientState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaGradientBody = { x: -9, y: 2.3, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaGradientPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaGradientFx] = []
    celebrated : boolean = false
    zoneId : string = "gradient"
    platforms : [RiyaGradientPlatform] = []
    skateCurve : [RiyaGradientCurveSample] = []
    driftRegions : [RiyaGradientDriftRegion] = []
    curves : [RiyaGradientCurve] = []
    guides : [RiyaGradientGuide] = []
    fieldVectors : [RiyaGradientFieldVector] = []
  }
  entity GradientTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }


  trait GradientBody = Body.traits.PlatformerBody -> RiyaGradientState {
    events {
      STEER: GRADIENT_STEER
      JUMP: GRADIENT_LEAP
      PLACE: GRADIENT_PLACE
      RESTART: GRADIENT_RESTART
      BODY_JUMPED: GRADIENT_JUMPED
      BODY_LANDED: GRADIENT_LANDED
      BODY_HAZARD: GRADIENT_HAZARD
      BODY_GOAL: GRADIENT_GOAL
      BODY_FELL: GRADIENT_FELL
      BODY_SKATE_START: GRADIENT_SKATE_ON
      BODY_SKATE_END: GRADIENT_SKATE_OFF
      SET_PLATFORMS: GRADIENT_SET_PLATFORMS
      SET_SKATE_CURVE: GRADIENT_SET_SKATE_CURVE
      SET_DRIFT_REGIONS: GRADIENT_SET_DRIFT_REGIONS
    }
    config {
      running: true
      spawn: { x: -9, y: 2.3, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: false
      skateSnap: 0.9
    }

    listens {
      STEER { dir : number! }
      JUMP { id : string }
      PLACE { x : number!, y : number! }
      CURVE_MOD_ADD { x0 : number!, x1 : number!, a : number!, b : number, h : number!, k : number! }
      CURVE_MOD_CLEAR { }
      CURVE_MOD_CLEAR_RANGE { x0 : number!, x1 : number! }
      SET_TUNING { jumpStrength : number, moveSpeed : number, gravity : number }
      SET_PLATFORMS { platforms : [PlatformerPlatform]! }
      SET_SKATE_CURVE { curve : [PlatformerCurveSample]! }
      SET_DRIFT_REGIONS { regions : [BodyDriftRegion]! }
      RESTART { id : string }
      RiyaGradientPlay.GRADIENT_LEAP -> GRADIENT_LEAP
      RiyaGradientPlay.GRADIENT_PLACE -> GRADIENT_PLACE
      RiyaGradientPlay.GRADIENT_RESTART -> GRADIENT_RESTART
      RiyaGradientPlay.GRADIENT_SET_DRIFT_REGIONS -> GRADIENT_SET_DRIFT_REGIONS
      RiyaGradientPlay.GRADIENT_SET_PLATFORMS -> GRADIENT_SET_PLATFORMS
      RiyaGradientPlay.GRADIENT_SET_SKATE_CURVE -> GRADIENT_SET_SKATE_CURVE
      RiyaGradientPlay.GRADIENT_STEER -> GRADIENT_STEER
    }
  }

  trait GradientGate = Gate.traits.ObjectiveFlow -> RiyaGradientState {
    events {
      PROGRESS: GRADIENT_PROGRESS
      GAME_END: GRADIENT_GAME_END
      RESTART: GRADIENT_RESTART
    }
    config { running: true }

    listens {
      PROGRESS { objectivesLeft : number, movesLeft : number }
      RESTART { id : string }
      RiyaGradientPlay.GRADIENT_PROGRESS -> GRADIENT_PROGRESS
      RiyaGradientPlay.GRADIENT_RESTART -> GRADIENT_RESTART
    }
  }

  trait GradientFx = Particles.traits.FxParticles -> RiyaGradientState {
    events {
      BURST: GRADIENT_BURST
    }
    config { running: true }

    listens {
      BURST { particles : [Fx] }
      RESTART { }
      GradientChallenge.GRADIENT_BURST -> GRADIENT_BURST
      RiyaGradientPlay.GRADIENT_BURST -> GRADIENT_BURST
    }
  }

  trait GradientPickup = Pickup.traits.Pickup -> RiyaGradientState {
    events {
      PICKED: GRADIENT_PICKED
      COLLECT: GRADIENT_COLLECT
      PICKUP_SET_COMPLETED: GRADIENT_PICKUP_SET_COMPLETED
      SET_FEATURES: GRADIENT_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }

    listens {
      BODY_MOVED { x : number!, y : number!, vx : number!, vy : number!, grounded : boolean!, skating : boolean!, speed : number! }
      SET_FEATURES { features : [PickupFeature]! }
      ADD_FEATURES { features : [PickupFeature]! }
      FEATURES_ACTIVE { updates : [PickupActiveUpdate]! }
      RESTART { id : string }
      GradientBody.BODY_MOVED -> BODY_MOVED
      RiyaGradientPlay.GRADIENT_SET_FEATURES -> GRADIENT_SET_FEATURES
    }
  }

  trait GradientLevelData -> @rebindable RiyaGradientState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "gradient"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          driftRegions: (array/map @config.driftRegions (fn d @d))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          fieldVectors: (array/map @config.fieldVectors (fn v @v))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaGradientPlatform]!
        stars : [RiyaGradientPickup]!
        skateCurve : [RiyaGradientCurveSample]
        driftRegions : [RiyaGradientDriftRegion]
        curveOverlay : [RiyaGradientCurve]
        guides : [RiyaGradientGuide]
        fieldVectors : [RiyaGradientFieldVector]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Gradient"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "z = 1 + 5·e^(−x²/18)"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "the gradient ∇f points the steepest way up; the drift follows −∇f downhill"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#a78bfa"
        @label "Region Color"
        @description "Zone band accent in the open world — the purple of the ∇f field arrows."
        @tier "presentation"
      entryY : number = 1.07
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 1.07
        @label "Exit Y"
