      previewTrait: @trait.GradientTutorialPreview
      steps: [
        { id: "intro", title: "Steepest Way Up", body: "The hill is z = 1 + 5·e^(−x²/18). Purple arrows are ∇f, pointing uphill. The hidden drift pulls you downhill." }
