  trait RiyaGradientPlay -> @rebindable RiyaGradientState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit GRADIENT_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            keyMap: { ArrowLeft: "GRADIENT_LEFT", KeyA: "GRADIENT_LEFT", ArrowRight: "GRADIENT_RIGHT", KeyD: "GRADIENT_RIGHT", ArrowUp: "GRADIENT_JUMP", KeyW: "GRADIENT_JUMP", Space: "GRADIENT_JUMP" }
            keyUpMap: { ArrowLeft: "GRADIENT_STOP", KeyA: "GRADIENT_STOP", ArrowRight: "GRADIENT_STOP", KeyD: "GRADIENT_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (array/concat
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])
                    []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: (array/concat [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.9), vx: (* @entity.body.vx 0.5), vy: (* @entity.body.vy 0.5), color: @config.riyaColor, label: "v" } ] @entity.fieldVectors)
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "GRADIENT_LEFT", right: "GRADIENT_RIGHT", up: "GRADIENT_JUMP" }, directionReleaseEvents: { left: "GRADIENT_STOP", right: "GRADIENT_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "gradient")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.guides @payload.guides)
        (set @entity.fieldVectors @payload.fieldVectors)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit GRADIENT_SET_PLATFORMS { platforms: @payload.platforms })
        (emit GRADIENT_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit GRADIENT_SET_DRIFT_REGIONS { regions: @payload.driftRegions })
        (emit GRADIENT_SET_FEATURES { features: @payload.stars })

      GRADIENT_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit GRADIENT_STEER { dir: -1 })

      GRADIENT_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit GRADIENT_STEER { dir: 1 })

      GRADIENT_STOP -> idle when (== @entity.active true)
        (emit GRADIENT_STEER { dir: 0 })

      GRADIENT_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit GRADIENT_LEAP {})

      GRADIENT_FELL -> idle when (== @entity.active true)
        (emit GRADIENT_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit GRADIENT_BURST { particles: (array/map [ "fx-gradient-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3 })) })

      GRADIENT_SKATE_ON -> idle when (== @entity.active true)
        (emit GRADIENT_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "longer arrow = steeper slope", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          {
            id: "fx-gradient-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat "x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4
          }
        ) })
      GRADIENT_PICKED -> idle when (== @entity.active true)
        (emit GRADIENT_BURST { particles: (array/map [ "fx-pickup-" ] (fn fid { id: (str/concat @fid @payload.id), type: "pickup", x: @payload.x, z: @payload.y, message: @payload.glyph, ttl: 2 })) })
      GRADIENT_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit GRADIENT_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      GRADIENT_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit GRADIENT_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "gradient = steepest ascent direction", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
        (emit GRADIENT_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      GRADIENT_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "gradient" })


      GRADIENT_TUTORIAL_DONE -> idle
        (emit GRADIENT_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "∇f points the steepest way up", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1 })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            guides: @entity.guides
            keyMap: { ArrowLeft: "GRADIENT_LEFT", KeyA: "GRADIENT_LEFT", ArrowRight: "GRADIENT_RIGHT", KeyD: "GRADIENT_RIGHT", ArrowUp: "GRADIENT_JUMP", KeyW: "GRADIENT_JUMP", Space: "GRADIENT_JUMP" }
            keyUpMap: { ArrowLeft: "GRADIENT_STOP", KeyA: "GRADIENT_STOP", ArrowRight: "GRADIENT_STOP", KeyD: "GRADIENT_STOP" }
            curves: (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: @config.starColor, radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (array/concat
                    (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] [])
                    []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: (array/concat [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.9), vx: (* @entity.body.vx 0.5), vy: (* @entity.body.vy 0.5), color: @config.riyaColor, label: "v" } ] @entity.fieldVectors)
          } ]
        })
    }

    emits {
      GRADIENT_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      GRADIENT_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      GRADIENT_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      GRADIENT_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (GRADIENT_LEAP), which accepts it only while grounded."
        @tier "domain"
      GRADIENT_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      GRADIENT_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      GRADIENT_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      GRADIENT_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      GRADIENT_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the hill — fires the equation fx burst."
        @tier "domain"
      GRADIENT_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the pickup glyph, the challenge trait applies id-conditional effects."
        @tier "domain"
      GRADIENT_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      GRADIENT_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      GRADIENT_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      GRADIENT_BURST -> external {
        particles : [RiyaGradientFx]
      }
        @description "Particle batch spawned on star pickup or pit respawn; fx-particles fades it."
        @tier "domain"
      GRADIENT_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted when a pickup is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      GRADIENT_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      GRADIENT_SET_PLATFORMS -> external {
        platforms : [RiyaGradientPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      GRADIENT_SET_SKATE_CURVE -> external {
        curve : [RiyaGradientCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate surface."
        @tier "domain"
      GRADIENT_SET_DRIFT_REGIONS -> external {
        regions : [RiyaGradientDriftRegion]!
      }
        @description "Renamed SET_DRIFT_REGIONS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA downhill drift."
        @tier "domain"
      GRADIENT_SET_FEATURES -> external {
        features : [RiyaGradientPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
    }

    listens {
      GradientBody.GRADIENT_FELL -> GRADIENT_FELL
      GradientBody.GRADIENT_SKATE_ON -> GRADIENT_SKATE_ON
      GradientGate.GRADIENT_GAME_END -> GRADIENT_GAME_END
      GradientLevelData.RIYA_LEVEL_DATA -> RIYA_LEVEL_DATA
      GradientPickup.GRADIENT_COLLECT -> GRADIENT_COLLECT
      GradientPickup.GRADIENT_PICKED -> GRADIENT_PICKED
      GradientPickup.GRADIENT_PICKUP_SET_COMPLETED -> GRADIENT_PICKUP_SET_COMPLETED
      GradientTutorial.GRADIENT_TUTORIAL_DONE -> GRADIENT_TUTORIAL_DONE
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaGradientPlatform]!
        stars : [RiyaGradientPickup]!
        skateCurve : [RiyaGradientCurveSample]
        driftRegions : [RiyaGradientDriftRegion]
        curveOverlay : [RiyaGradientCurve]
        guides : [RiyaGradientGuide]
        fieldVectors : [RiyaGradientFieldVector]
      }
    }

    config {
