  trait GradientChallenge -> @rebindable RiyaGradientState [game-core, instance] {
    initial: idle

    state idle {
      GRADIENT_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "scale")
          (emit GRADIENT_BURST { particles: (array/concat
            { id: "narrative-boost-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "|∇f| × 1.5", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1 }
            { id: "narrative-boost-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.6), y: 0, message: "gradient scaled", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1 }
          ) })
          null)
    }

    emits {
      GRADIENT_BURST -> external {
        particles : [RiyaGradientFx]
      }
        @description "Particle batch spawned on the scale-boost narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      GradientPickup.GRADIENT_PICKED -> GRADIENT_PICKED
      GRADIENT_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "gradient"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaGradientClear -> @rebindable RiyaGradientState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "GRADIENT_NEXT", variant: "primary" } ]
        })

      GRADIENT_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RiyaGradientPlay.RIYA_LEVEL_SOLVED -> RIYA_LEVEL_SOLVED
      RIYA_LEVEL_SOLVED { level : string }
      GRADIENT_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-gradient"
        @label "Next Path"
        @tier "presentation"
      clearTitle : string = "Gradient clear"
        @label "Clear Title"
        @tier "presentation"
      clearSubtitle : string = "Arrows pointed uphill; you fought the fall."
        @label "Clear Subtitle"
        @tier "presentation"
    }
  }

  page "/riya-gradient" as RiyaGradientPage -> GradientLevelData, GradientBody, GradientGate, GradientFx, GradientPickup, GradientTutorial, RiyaGradientGenre, RiyaGradientPlay, GradientChallenge, RiyaGradientClear
